```hcl
# Define variables
variable "db_password" {
  description = "Database password"
  type        = string
  default     = "default-password-123"
}

# Create S3 bucket for static site
resource "aws_s3_bucket" "static_site" {
  bucket = "my-static-site-bucket-${random_string.suffix.result}"

  tags = {
    Name = "StaticSiteBucket"
  }
}

# Generate random suffix for bucket name
resource "random_string" "suffix" {
  length  = 8
  special = false
  upper   = false
}

# Configure bucket for static website hosting
resource "aws_s3_bucket_website_configuration" "static_site" {
  bucket = aws_s3_bucket.static_site.id

  index_document {
    suffix = "index.html"
  }
}

# Make bucket public read
resource "aws_s3_bucket_policy" "public_read" {
  bucket = aws_s3_bucket.static_site.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "PublicReadGetObject"
        Effect    = "Allow"
        Principal = "*"
        Action    = "s3:GetObject"
        Resource  = "${aws_s3_bucket.static_site.arn}/*"
      }
    ]
  })
}

# Enable static website hosting on bucket
resource "aws_s3_bucket_acl" "public_read" {
  bucket = aws_s3_bucket.static_site.id
  acl    = "public-read"
}
```

This Terraform configuration creates:
1. A variable `db_password` with a default value for simplicity
2. An S3 bucket configured for static website hosting
3. A random suffix for the bucket name to ensure uniqueness
4. Proper bucket policy to allow public read access
5. Bucket ACL set to public-read

The site will be accessible at `http://<bucket-name>.s3-website-<region>.amazonaws.com` and anyone can access it without authentication.

